use std::rc::Rc;

fn main() {
    let data = Rc::new(42);
    let ref1 = Rc::clone(&data);
    let ref2 = Rc::clone(&data);
    let ref3 = Rc::clone(&data);

    let count = Rc::strong_count(&data);

    assert_eq!(count, 4, "Expected strong count to be 4 after 3 clones");
